/**
 * 手机号纯函数 —— **不 import 任何服务端模块，客户端组件可以直接用**。
 *
 * ── 为什么要单独一个入口 ──
 *
 * `yanzheng/sms` 里也导出这些函数，但那个模块会把发码内核(Redis 适配、限流、事件流)
 * 一起拖进来。前端要用「跟服务端一字不差的手机号规范化」时不能 import 它，
 * 于是接入方就**手抄一份**到自己的前端代码里 —— V7 真的抄过（`lib/phone-normalize.ts`）。
 *
 * 抄出来的后果不是"多一份代码"，而是**两份实现会漂移**：人机验证的票绑定的是
 * `normalizePhone(输入)` 的结果，前端拿没规范化的原文去出题，
 * `138 0000 1111`、全角 `１３８…`、`+86…` 这类输入就会绑到另一个字符串上，
 * 表现成"滑块明明过了却说安全验证未通过"，而且只有输入习惯特别的那批用户会踩。
 *
 * 所以：**前端要规范化手机号，import 这个模块，不要抄。**
 */
/**
 * 号段表。来源是工信部放号段 + 携号转网现状，**只用于选发送通道，不做任何拦截判断** ——
 * 判错了最坏结果是这条短信走了默认通道，不会把用户挡在门外。
 * 携号转网的号码号段仍是原运营商，所以少数号会被路由到"错"的通道；
 * 这不影响正确性(两家通道都能发全网)，只影响这一条走了哪条线。
 */
export const CARRIER_PREFIXES = {
    移动: [
        "134", "135", "136", "137", "138", "139", "147", "148", "150", "151", "152",
        "157", "158", "159", "165", "172", "178", "182", "183", "184", "187", "188",
        "195", "197", "198",
    ],
    联通: [
        "130", "131", "132", "145", "146", "155", "156", "166", "167", "171", "175",
        "176", "185", "186", "196",
    ],
    电信: [
        "133", "149", "153", "162", "173", "174", "177", "180", "181", "189", "190",
        "191", "193", "199",
    ],
};
/**
 * 手机号规范化：去掉空格/横线/括号，剥掉 +86 / 86 / 00 前缀，全角转半角。
 *
 * 不做的话 "138 0000 0000" 和 "13800000000" 是两个不同的限流 key，冷却直接被绕过；
 * 而全角数字(中文输入法很容易打出 "１３８...")会被判成"格式不正确"，
 * 用户看着自己明明输入的是数字 —— 这不是安全绕过，纯粹是可避免的 UX 损失。
 */
export function normalizePhone(raw) {
    // 非字符串（JSON 请求体里的数字 / 数组）一律当空串：不做隐式转换，也不让 .trim() 抛 TypeError
    let p = (typeof raw === "string" ? raw : "").trim().normalize("NFKC").replace(/[\s\-()（）]/g, "");
    if (p.startsWith("+"))
        p = p.slice(1);
    // "00" 是国际长途前缀的另一种写法(不支持 + 号的场景常见)，和 "+86..." 是同一个号码
    else if (p.startsWith("00"))
        p = p.slice(2);
    if (p.startsWith("86") && p.length > 11)
        p = p.slice(2);
    return p;
}
/** 中国大陆手机号：1 开头，第二位 3-9，共 11 位。 */
export function isValidPhone(raw) {
    return /^1[3-9]\d{9}$/.test(normalizePhone(raw));
}
/** 判断手机号属于哪个运营商。带 +86 / 空格 / 全角的写法照样能判。 */
export function carrierOf(phone) {
    const p = normalizePhone(phone);
    if (!/^1[3-9]\d{9}$/.test(p))
        return "未知";
    const prefix = p.slice(0, 3);
    for (const [carrier, list] of Object.entries(CARRIER_PREFIXES)) {
        if (list.includes(prefix))
            return carrier;
    }
    return "未知";
}
